param([string]$Root=(Resolve-Path (Join-Path $PSScriptRoot "..")).Path); $ErrorActionPreference="Stop"; & (Join-Path $Root "scripts/validate-security-claims.ps1") -Root $Root; $p=Get-Content (Join-Path $Root "frontend/src/app/rootmaster/page.tsx") -Raw; if($p -notmatch "RootMaster operations are unavailable"){throw "RootMaster unavailable state missing."}; if($p -notmatch "does not provide firmware flashing"){throw "Qualified disabled-operation wording missing."}; if($p -match "(?i)onClick|fetch\(|axios|flash\(|unlock\(|bypass\(|register modification\s*[:=]"){throw "Executable unsupported operation remains in RootMaster route."}; $d=Get-Content (Join-Path $Root "docs/security/ISSUE_63_CAPABILITY_EVIDENCE_REGISTER.json") -Raw|ConvertFrom-Json; if(@($d.claims).Count -lt 7){throw "Register does not cover required claim families."}; Write-Output "Issue #63 acceptance tests passed: register structure, claim rejection, qualified wording, and disabled-operation assertions."
